package com.dreamcore.workspace.departure;
import com.dreamcore.workspace.conversation.ConversationService;import com.dreamcore.workspace.objectlifecycle.ObjectScopeLifecycle;import com.dreamcore.workspace.retention.RetentionClock;import java.time.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
/** One bounded reconciliation pass. Claims are not cleanup success; V20/V33 workers supply actual erasure receipts. */
@Service public class DepartureProcessor {
 private final JdbcTemplate db;private final ConversationService conversations;private final ObjectScopeLifecycle objects;private final DepartureMaterialBridge materials;private final RetentionClock clock;private final DepartureResidualCleanup residual;private final DepartureArchiveService archives;
 public DepartureProcessor(JdbcTemplate db,ConversationService conversations,ObjectScopeLifecycle objects,DepartureMaterialBridge materials,RetentionClock clock,DepartureResidualCleanup residual,DepartureArchiveService archives){this.db=db;this.conversations=conversations;this.objects=objects;this.materials=materials;this.clock=clock;this.residual=residual;this.archives=archives;}
 public List<UUID> candidates(){return db.queryForList("SELECT id FROM departure_executions WHERE state NOT IN('COMPLETE','CANCELLED') ORDER BY checked_at NULLS FIRST,effective_at LIMIT 5",UUID.class);}
 private Instant time(Map<String,Object>e,String key){return ((java.sql.Timestamp)e.get(key)).toInstant();}
 private void event(UUID id,String action){var r=db.queryForMap("SELECT revision,state FROM departure_executions WHERE id=?",id);db.update("INSERT INTO departure_events(id,execution_id,revision,action,state,created_at) VALUES (?,?,?,?,?,?)",UUID.randomUUID(),id,r.get("revision"),action,r.get("state"),java.sql.Timestamp.from(clock.now()));}
 private void state(UUID id,String next,String action){int changed=db.update("UPDATE departure_executions SET state=?,revision=revision+1 WHERE id=? AND state<>?",next,id,next);if(changed>0)event(id,action);}
 @Transactional public void process(UUID id){var found=db.queryForList("SELECT tenant_id FROM departure_executions WHERE id=?",UUID.class,id);if(found.isEmpty())return;UUID tenant=found.getFirst();db.queryForList("SELECT id FROM tenants WHERE id=? FOR UPDATE",tenant);var e=db.queryForMap("SELECT * FROM departure_executions WHERE id=? FOR UPDATE",id);if(Set.of("COMPLETE","CANCELLED").contains(e.get("state")))return;UUID owner=(UUID)e.get("target_account_id");Instant at=time(e,"effective_at"),deadline=time(e,"deadline"),now=clock.now();db.update("UPDATE departure_executions SET checked_at=?,worker_attempts=worker_attempts+1,error_code=NULL WHERE id=?",java.sql.Timestamp.from(now),id);
  stop(tenant,owner,id);
  if(e.get("state").equals("RESTORING")&&now.isBefore(deadline)){var materialState=materials.restore(id,100);boolean objectComplete=true;if(db.queryForObject("SELECT count(*) FROM object_lifecycle_scopes WHERE execution_id=?",Integer.class,id)>0)objectComplete=objects.restoreScope(tenant,id,100).complete();
   if(materialState.complete()&&objectComplete){var m=db.queryForMap("SELECT m.*,a.status AS account_status FROM tenant_memberships m JOIN accounts a ON a.id=m.account_id WHERE m.tenant_id=? AND m.account_id=?",tenant,owner);boolean securityStop=Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM governance_security_stops WHERE tenant_id=? AND account_id=? AND created_at>?)",Boolean.class,tenant,owner,e.get("effective_at")));boolean exiting=Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM departure_executions WHERE tenant_id=? AND kind='TENANT_EXIT' AND state<>'CANCELLED')",Boolean.class,tenant));if(!m.get("account_status").equals("ACTIVE")||!m.get("status").equals("DISABLED")||!m.get("management_version").equals(e.get("stopped_member_version"))||securityStop||exiting){db.update("UPDATE departure_executions SET error_code='DEPARTURE_IDENTITY_CHANGED' WHERE id=?",id);return;}
    state(id,"CANCELLED","OFFBOARD_CANCELLED");db.update("UPDATE departure_executions SET cancelled_at=? WHERE id=?",java.sql.Timestamp.from(now),id);if(e.get("prior_member_status").equals("ACTIVE"))db.update("UPDATE tenant_memberships SET status='ACTIVE',management_version=management_version+1 WHERE tenant_id=? AND account_id=?",tenant,owner);
   }return;
  }
  if(owner==null&&now.isBefore(deadline))return;
  if(!now.isBefore(deadline))state(id,"CLEANING","CLEANUP_WINDOW_STARTED");
  var materialState=materials.isolate(id,100);boolean expiredRestore=!now.isBefore(deadline)&&Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM object_lifecycle_scopes WHERE execution_id=? AND state IN('RESTORING','RESTORED'))",Boolean.class,id));var objectState=expiredRestore?objects.resumeExpiredScope(tenant,owner,id,at,deadline,100):objects.isolateScope(tenant,owner,id,at,deadline,100);db.update("UPDATE departure_executions SET isolation_complete=? WHERE id=?",materialState.discoveryComplete()&&objectState.discoveryComplete(),id);
  if(now.isBefore(deadline)){if(materialState.discoveryComplete()&&objectState.discoveryComplete())state(id,"ISOLATED","PRIVATE_CONTENT_ISOLATED");return;}
  materialState=materials.purge(id,100);objectState=objects.purgeScope(tenant,owner,id,100);db.update("UPDATE departure_executions SET materials_complete=?,objects_complete=? WHERE id=?",materialState.complete(),objectState.complete(),id);
  boolean archivesComplete=archives.cleanupExecution(id);boolean residualComplete=residual.clean(tenant,owner);
  if(materialState.complete()&&objectState.complete()&&archivesComplete&&residualComplete&&Boolean.TRUE.equals(db.queryForObject("SELECT stop_complete FROM departure_executions WHERE id=?",Boolean.class,id))){state(id,"COMPLETE","ONLINE_CLEANUP_COMPLETE");db.update("UPDATE departure_executions SET completed_at=? WHERE id=?",java.sql.Timestamp.from(now),id);}
 }
 private void stop(UUID tenant,UUID owner,UUID id){
  var tasks=db.queryForList("SELECT id FROM conversation_tasks WHERE tenant_id=? AND (?::uuid IS NULL OR requested_by=?) AND status IN('QUEUED','RUNNING') ORDER BY id LIMIT 100",UUID.class,tenant,owner,owner);conversations.interruptTasks(tenant,tasks,owner==null?"TASK_TENANT_EXIT":"TASK_MEMBER_OFFBOARDED");

  if(Boolean.TRUE.equals(db.queryForObject("SELECT to_regclass('ongoing_plans') IS NOT NULL",Boolean.class)))db.update("UPDATE ongoing_plans SET status='STOPPED',runtime_state='IDLE',reason=?,execution_epoch=execution_epoch+1,revision=revision+1,updated_at=now(),retry_requested=false WHERE id IN(SELECT id FROM ongoing_plans WHERE tenant_id=? AND (?::uuid IS NULL OR owner_id=?) AND status NOT IN('STOPPED','EXPIRED') ORDER BY id LIMIT 100)",owner==null?"TENANT_EXIT":"MEMBER_OFFBOARDED",tenant,owner,owner);
  long pending=db.queryForObject("SELECT count(*) FROM conversation_tasks WHERE tenant_id=? AND (?::uuid IS NULL OR requested_by=?) AND status IN('QUEUED','RUNNING')",Long.class,tenant,owner,owner);if(Boolean.TRUE.equals(db.queryForObject("SELECT to_regclass('ongoing_plans') IS NOT NULL",Boolean.class)))pending+=db.queryForObject("SELECT count(*) FROM ongoing_plans WHERE tenant_id=? AND (?::uuid IS NULL OR owner_id=?) AND status NOT IN('STOPPED','EXPIRED')",Long.class,tenant,owner,owner);
  db.update("UPDATE departure_executions SET stop_complete=? WHERE id=?",pending==0,id);
 }
 @Transactional public void failed(UUID id){db.update("UPDATE departure_executions SET error_code='DEPARTURE_RECONCILIATION_FAILED',worker_attempts=worker_attempts+1,checked_at=now() WHERE id=? AND state NOT IN('COMPLETE','CANCELLED')",id);}
}
